package ca.yorku.eecs3311.coursepilot.domain.model;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="study_plan_items") public class StudyPlanItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="plan_id") StudyPlan plan; @Column(nullable=false) LocalDate scheduledDate; @Column(nullable=false) int sequenceNumber; @Column(nullable=false,length=500) String activity; @Column(nullable=false) int minutes; @Column(nullable=false) boolean completed=false; @Column(nullable=false) int actualMinutes=0; protected StudyPlanItem(){} public StudyPlanItem(StudyPlan p,LocalDate date,int seq,String activity,int minutes){plan=p;scheduledDate=date;sequenceNumber=seq;this.activity=activity;this.minutes=minutes;} public Long getId(){return id;} public StudyPlan getPlan(){return plan;} public LocalDate getScheduledDate(){return scheduledDate;} public int getSequenceNumber(){return sequenceNumber;} public String getActivity(){return activity;} public int getMinutes(){return minutes;} public boolean isCompleted(){return completed;} public int getActualMinutes(){return actualMinutes;} public void update(LocalDate date,String activity,int minutes,boolean completed,int actualMinutes){this.scheduledDate=date;this.activity=activity;this.minutes=minutes;this.completed=completed;this.actualMinutes=actualMinutes;} }
